import type { Metadata } from "next";
import type { ReactNode } from "react";
import { Work_Sans } from "next/font/google";

import "./globals.css";

const workSans = Work_Sans({
  variable: "--font-work-sans",
  subsets: ["latin"],
  display: "swap",
});

export const metadata: Metadata = {
  title: "Apsu | Healthcare in your language",
  description:
    "Online care from US-licensed physicians, supported in more than 40 languages.",
};

interface RootLayoutProps {
  children: ReactNode;
}

export default function RootLayout({
  children,
}: Readonly<RootLayoutProps>) {
  return (
    <html lang="en" className={`${workSans.variable} antialiased`}>
      <body>{children}</body>
    </html>
  );
}import { LocalizedHome } from "@/components/localized-home";
import { getHomePageContent } from "@/lib/content";

export default async function Home() {
  const content = await getHomePageContent();
  return <LocalizedHome baseContent={content} />;
}
@import "tailwindcss";

:root {
  --ink: #0b331f;
  --evergreen: #07351f;
  --mint: #c5fbe8;
  --aqua: #c8f8f5;
  --pink: #fbd3fa;
  --canvas: #faf9f4;
}

@theme inline {
  --color-ink: var(--ink);
  --color-evergreen: var(--evergreen);
  --color-mint: var(--mint);
  --color-aqua: var(--aqua);
  --color-pink: var(--pink);
  --color-canvas: var(--canvas);
  --font-sans: var(--font-work-sans);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  overflow-x: clip;
}

body {
  min-height: 100vh;
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font-family: var(--font-work-sans), Arial, sans-serif;
}

button,
input,
textarea,
select {
  font-family: inherit;
}

@keyframes trust-marquee {
  from {
    transform: translateX(0);
  }

  to {
    transform: translateX(-50%);
  }
}

button,
a,
summary,
input {
  -webkit-tap-highlight-color: transparent;
}

:focus-visible {
  outline: 3px solid #0aa672;
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    transition-delay: 0ms !important;
  }
}

