      />
      <span
        aria-hidden="true"
        className="relative size-6 shrink-0"
      >
        <span
          className={`absolute left-[1.25px] top-[1.25px] grid size-[21.5px] place-items-center rounded-full border-2 ${
            checked ? "border-[#102b1c]" : "border-[#afc1b6]"
          }`}
        >
          <span
            className={`size-3 rounded-full ${
              checked ? "bg-[#102b1c]" : "border border-[#afc1b6]"
            }`}
          />
        </span>
      </span>
      {label}
    </label>
  );
}

interface ScoreRingProps {
  score: number | null;
  label: string;
  progress: number;
}

function ScoreRing({ score, label, progress }: ScoreRingProps) {
  const greenLength =
    score === null ? 0 : Math.min(42, Math.max(22, progress * 0.44));

  return (
    <div className="relative mx-auto size-[137px] shrink-0 xl:size-[217px]">
      <svg viewBox="0 0 217 217" className="size-full" aria-hidden="true">
        <circle
          cx="108.5"
          cy="108.5"
          r="107"
          fill="none"
          stroke="#a0a0a1"
          strokeWidth="1"
          strokeDasharray="2 4 6 8"
        />
        <circle
          cx="108.5"
          cy="108.5"
          r="93.4"
          className="xl:hidden"
          fill="none"
          stroke="#009269"
          strokeOpacity="0.2"
          strokeWidth="10"
          strokeLinecap="round"
          pathLength="100"
          strokeDasharray="39 61"
          transform="rotate(104 108.5 108.5)"
        />
        <circle
          cx="108.5"
          cy="108.5"
          r="88.4"
          className="hidden xl:block"
          fill="none"
          stroke="#009269"
          strokeOpacity="0.2"
          strokeWidth="10"
          strokeLinecap="round"
          pathLength="100"
          strokeDasharray="39 61"
          transform="rotate(104 108.5 108.5)"
        />
        {score !== null ? (
          <>
            <circle
              cx="108.5"
              cy="108.5"
              r="93.4"
              className="xl:hidden"
              fill="none"
              stroke="#009269"
              strokeWidth="10"
              strokeLinecap="round"
              pathLength="100"
              strokeDasharray={`${greenLength} ${100 - greenLength}`}
              transform="rotate(-74 108.5 108.5)"
            />
            <circle
              cx="108.5"
              cy="108.5"
              r="88.4"
              className="hidden xl:block"
              fill="none"
              stroke="#009269"
              strokeWidth="10"
              strokeLinecap="round"
              pathLength="100"
              strokeDasharray={`${greenLength} ${100 - greenLength}`}
              transform="rotate(-74 108.5 108.5)"
            />
          </>
        ) : null}
      </svg>
      <div className="absolute inset-0 grid place-items-center text-center text-[#111111]">
        <div>
          <p className="text-[52px] font-normal leading-[1.1]">
            {score ?? "--"}
          </p>
          <p className="mt-1 text-sm leading-[1.6] xl:text-lg xl:leading-6">
            Your {label}
          </p>
        </div>
      </div>
    </div>
  );
}

interface MeasurementState {
  feetValid: boolean;
  inchesValid: boolean;
  weightValid: boolean;
  score: number | null;
}

function evaluateMeasurements(
  feetValue: string,
  inchesValue: string,
  weightValue: string,
): MeasurementState {
  const feet = Number(feetValue);
  const inches = Number(inchesValue);
  const weight = Number(weightValue);

  const feetValid =
    feetValue.trim() !== "" &&
    Number.isInteger(feet) &&
    feet >= 3 &&
    feet <= 8;
  const inchesValid =
    inchesValue.trim() !== "" &&
    Number.isInteger(inches) &&
    inches >= 0 &&
    inches <= 11;
  const weightValid =
    weightValue.trim() !== "" &&
    Number.isFinite(weight) &&
    weight >= 50 &&
    weight <= 1000;

  if (!feetValid || !inchesValid || !weightValid) {
    return { feetValid, inchesValid, weightValid, score: null };
  }

  const totalInches = feet * 12 + inches;
  const score = (weight / totalInches ** 2) * 703;

  return {
    feetValid,
    inchesValid,
    weightValid,
    score: Math.round(score * 10) / 10,
  };
}

function evaluateMetricMeasurements(
  heightValue: string,
  weightValue: string,
): MeasurementState {
  const height = Number(heightValue);
  const weight = Number(weightValue);
  const feetValid =
    heightValue.trim() !== "" &&
    Number.isFinite(height) &&
    height >= 92 &&
    height <= 272;
  const weightValid =
    weightValue.trim() !== "" &&
    Number.isFinite(weight) &&
    weight >= 23 &&
    weight <= 454;

  if (!feetValid || !weightValid) {
    return { feetValid, inchesValid: true, weightValid, score: null };
  }

  const score = weight / (height / 100) ** 2;
  return {
    feetValid,
    inchesValid: true,
    weightValid,
    score: Math.round(score * 10) / 10,
  };
}

export function BmiCalculator({
  copy = defaultCopy,
  initialMode = "empty",
}: BmiCalculatorProps) {
  const initialFeet = initialMode === "empty" ? "" : "5";
  const initialInches = initialMode === "empty" ? "" : "8";
  const initialWeight =
    initialMode === "empty" ? "" : initialMode === "invalid" ? "0" : "165";
  const initialScore =
    initialMode === "result"
