          cy="108.5"
          r="93.4"
          className="xl:hidden"
          fill="none"
          stroke="#009269"
          strokeOpacity="0.2"
          strokeWidth="10"
          strokeLinecap="round"
          pathLength="100"
          strokeDasharray="39 61"
          transform="rotate(104 108.5 108.5)"
        />
        <circle
          cx="108.5"
          cy="108.5"
          r="88.4"
          className="hidden xl:block"
          fill="none"
          stroke="#009269"
          strokeOpacity="0.2"
          strokeWidth="10"
          strokeLinecap="round"
          pathLength="100"
          strokeDasharray="39 61"
          transform="rotate(104 108.5 108.5)"
        />
        {score !== null ? (
          <>
            <circle
              cx="108.5"
              cy="108.5"
              r="93.4"
              className="xl:hidden"
              fill="none"
              stroke="#009269"
              strokeWidth="10"
              strokeLinecap="round"
              pathLength="100"
              strokeDasharray={`${greenLength} ${100 - greenLength}`}
              transform="rotate(-74 108.5 108.5)"
            />
            <circle
