              className="flex h-[542px] min-h-0 flex-col rounded-xl border border-[#bcffe6] bg-white p-3 text-[#111111] shadow-[0_4px_21.6px_rgba(2,29,23,0.06)] xl:h-[496px] xl:rounded-2xl xl:p-6"
