}

interface MeasurementState {
  feetValid: boolean;
  inchesValid: boolean;
  weightValid: boolean;
  score: number | null;
}

function evaluateMeasurements(
  feetValue: string,
  inchesValue: string,
  weightValue: string,
): MeasurementState {
  const feet = Number(feetValue);
  const inches = Number(inchesValue);
  const weight = Number(weightValue);

  const feetValid =
    feetValue.trim() !== "" &&
    Number.isInteger(feet) &&
    feet >= 3 &&
    feet <= 8;
  const inchesValid =
    inchesValue.trim() !== "" &&
    Number.isInteger(inches) &&
    inches >= 0 &&
    inches <= 11;
  const weightValid =
    weightValue.trim() !== "" &&
    Number.isFinite(weight) &&
    weight >= 50 &&
    weight <= 1000;

  if (!feetValid || !inchesValid || !weightValid) {
    return { feetValid, inchesValid, weightValid, score: null };
  }

  const totalInches = feet * 12 + inches;
  const score = (weight / totalInches ** 2) * 703;

  return {
    feetValid,
    inchesValid,
    weightValid,
    score: Math.round(score * 10) / 10,
  };
}

function evaluateMetricMeasurements(
  heightValue: string,
  weightValue: string,
): MeasurementState {
  const height = Number(heightValue);
  const weight = Number(weightValue);
  const feetValid =
    heightValue.trim() !== "" &&
    Number.isFinite(height) &&
    height >= 92 &&
    height <= 272;
  const weightValid =
    weightValue.trim() !== "" &&
    Number.isFinite(weight) &&
    weight >= 23 &&
    weight <= 454;

  if (!feetValid || !weightValid) {
    return { feetValid, inchesValid: true, weightValid, score: null };
  }

  const score = weight / (height / 100) ** 2;
  return {
    feetValid,
    inchesValid: true,
    weightValid,
    score: Math.round(score * 10) / 10,
  };
}

